def chk(content):
    p=pathlib.Path("/tmp/lp")
    if p.exists(): shutil.rmtree(p)
    p.mkdir(); (p/"a.nix").write_text(content)
    r=subprocess.run([BIN,"check","-o","errfmt","a.nix"],capture_output=True,text=True,cwd=p)
    print(f"{content!r:50} -> {r.stdout.strip()!r}")

