for inn in inners:
    chk(f"({inn})\n")
print("--- binding")
for inn in inners:
    chk("{ a = ("+inn+"); }\n")
print("--- list element")
for inn in inners:
    chk(f"[ ({inn}) ]\n")
print("--- lambda body")
for inn in inners:
    chk(f"x: ({inn})\n")
