                # parse as lambda argument
                return True
            if k=="TOKEN_L_BRACE" and self.is_lambda_start():
                return True
            return True
        return False

    def parse_select_expr(self):
        # parses a primary / value, then suffixes: .attrpath (select), ? attrpath (hasattr), also lambda if this position starts lambda (for arguments/list elements)
        if self.is_lambda_start():
            return self.parse_lambda()
        expr=self.parse_primary()
        # suffix loop
        while True:
            if self.at("TOKEN_DOT"):
                # select
                children=[expr, self.bump()]
                attrpath=self.parse_attrpath(); children.append(attrpath)
