                if self.at("TOKEN_OR"):
                    # 'or' token: could be default
                    children.append(self.bump())
                    default=self.parse_select_expr(); children.append(default)
                node=Node("NODE_SELECT", children); expr.parent=node; attrpath.parent=node; expr=node; continue
            if self.at("TOKEN_QUESTION"):
                children=[expr, self.bump()]
                attrpath=self.parse_attrpath(); children.append(attrpath)
                node=Node("NODE_HAS_ATTR", children); expr.parent=node; attrpath.parent=node; expr=node; continue
            break
        return expr

    def parse_primary(self):
        k=self.cur_kind()
        if k is None:
            self.err_eof(None)
            n=Node("NODE_ERROR",[]); n._start=len(self.text); n._end=len(self.text); return n
        if k=="TOKEN_L_PAREN":
            children=[self.bump()]
            inner=self.parse_expr(); children.append(inner)
            if self.at("TOKEN_R_PAREN"):
                children.append(self.bump())
            else:
                self.expect("TOKEN_R_PAREN", None)
            node=Node("NODE_PAREN", children); inner.parent=node; return node
        if k=="TOKEN_REC":
            # rec attrset: rec expects {
            return self.parse_attrset(is_rec=True)
        if k=="TOKEN_L_BRACE":
