            node=Node("NODE_UNARY_OP",[op,operand]); operand.parent=node; return node
        # unexpected token
        # record error and consume token as error node
        t=self.bump()
        msg=f"Unexpected {t.kind} at {self.byte_off(t.start)}..{self.byte_off(t.end)}, wanted any of {PRIMARY_WANTED}"
        self.errors.append(ParseError(msg,t.start,t.end))
        return Node("NODE_ERROR",[t])

    def parse_list(self):
        children=[self.bump()] # [
        # elements: parse_select_expr-like but using parse_list_value which is parse_select_expr (it handles lambda)
        while not self.at_eof() and not self.at("TOKEN_R_BRACK"):
