        if self.at("TOKEN_R_BRACK"):
            children.append(self.bump())
        else:
            self.expect("TOKEN_R_BRACK", None)
        return Node("NODE_LIST", children)

    def parse_string(self):
        # String start token present
        start_tok=self.bump()
        children=[start_tok]
        # determine double or indented? both same token kind; start text '"' or "''"
        while True:
            k=self.cur_kind()
            if k=="TOKEN_STRING_END":
                children.append(self.bump()); break
            elif k=="TOKEN_STRING_CONTENT":
                children.append(self.bump()); continue
            elif k=="TOKEN_INTERPOL_START":
                interp_children=[self.bump()]
                e=self.parse_expr(); interp_children.append(e)
