                self.err_eof(STRING_WANTED)
                # then expect STRING_END with wanted [TOKEN_STRING_END]
                self.err_eof("[TOKEN_STRING_END]")
                break
            else:
                # unexpected token e.g. TOKEN_ERROR for unterminated content
                t=self.bump()
                msg=f"Unexpected {t.kind} at {self.byte_off(t.start)}..{self.byte_off(t.end)}, wanted any of {STRING_WANTED}"
                self.errors.append(ParseError(msg,t.start,t.end))
                children.append(Node("NODE_ERROR",[t]))
                # after consuming error token (unterminated), loop will hit EOF and produce the two EOF errors above
                continue
        return Node("NODE_STRING", children)


def parse_source(text):
    p=Parser(text)
    root=p.parse_root()
    # set parents recursively (Node init already for children passed, but mutated children need fix)
    def fix(node):
        for ch in node.children:
            if isinstance(ch, Node):
                ch.parent=node; fix(ch)
    fix(root)
    root.parent=None
    return root, p.errors

