# ---------------------------------------------------------------------------
# AST nodes
# ---------------------------------------------------------------------------

class Node:
    __slots__ = ("kind","children","parent","_start","_end")
    def __init__(self, kind, children=None):
        self.kind = kind
        self.children = children if children is not None else []
