            msg=f"Unexpected {first.kind} at {self.byte_off(start)}..{self.byte_off(end)}"
        self.errors.append(ParseError(msg,start,end))
        if self.at(kind):
            self.bump(); return True
        else:
            # EOF
            self.err_eof(wanted)
            return False

    def byte_off(self, idx):
        # convert char index to utf8 byte offset
        # cache
        return len(self.text[:idx].encode('utf-8'))

    # ---- parsing entry point ----
    def parse_root(self):
        children=[]
        if self.at_eof():
            self.err_eof(None)
            root=Node("NODE_ROOT", children)
            root._start=0; root._end=len(self.text)
            return root
        expr=self.parse_expr()
        children.append(expr)
        if not self.at_eof():
            # leftover tokens: Unexpected token at range from first leftover to last token
            start=self.cur().start; end=self.cur().end
            err_children=[]
            while not self.at_eof():
                t=self.bump(); end=t.end; err_children.append(t)
            errnode=Node("NODE_ERROR", err_children)
            children.append(errnode)
            self.errors.append(ParseError(f"Unexpected token at {self.byte_off(start)}..{self.byte_off(end)}", start, end))
        root=Node("NODE_ROOT", children)
        return root

    # ---- expression dispatch ----
    def parse_expr(self):
        # handle keywords / lambda / operators
        k=self.cur_kind()
        if k is None:
            self.err_eof(None)
            n=Node("NODE_ERROR", []); n._start=len(self.text); n._end=len(self.text); return n
        if k=="TOKEN_IF":
            return self.parse_if()
        if k=="TOKEN_LET":
            # legacy let if next token is L_BRACE
            if self.peek_kind(1)=="TOKEN_L_BRACE":
                return self.parse_legacy_let()
            return self.parse_let()
        if k=="TOKEN_WITH":
            return self.parse_with()
        if k=="TOKEN_ASSERT":
            return self.parse_assert()
        # lambda detection handled in parse_binop's unary/primary chain? Lambda is lowest precedence: parse lambda before binop if pattern.
        # Detect lambda start:
        if self.is_lambda_start():
            return self.parse_lambda()
        return self.parse_binop(0)

    def is_lambda_start(self):
        k=self.cur_kind()
        if k=="TOKEN_IDENT":
            # ident : or ident @ {
            if self.peek_kind(1)=="TOKEN_COLON":
                return True
            if self.peek_kind(1)=="TOKEN_AT" and self.peek_kind(2)=="TOKEN_L_BRACE":
                return True
            return False
        if k=="TOKEN_L_BRACE":
            # need scan to matching } (account nesting/interp) and see : or @ ident :
            idx=self.pos
            depth=0
            # we need token-level scan; braces include L_BRACE/R_BRACE and INTERPOL... dynamic inside pattern defaults may have braces.
            # Simple scan counting L_BRACE/INTERPOL_START as +1, R_BRACE/INTERPOL_END as -1.
            i=idx
            while i < len(self.toks):
                kk=self.toks[i].kind
                if kk in ("TOKEN_L_BRACE","TOKEN_INTERPOL_START"):
                    depth+=1
                elif kk in ("TOKEN_R_BRACE","TOKEN_INTERPOL_END"):
                    depth-=1
                    if depth==0:
                        # next token
                        nxt=self.toks[i+1].kind if i+1 < len(self.toks) else None
                        if nxt=="TOKEN_COLON":
                            return True
                        if nxt=="TOKEN_AT":
                            # { } @ ident :
                            if i+3 < len(self.toks) and self.toks[i+2].kind=="TOKEN_IDENT" and self.toks[i+3].kind=="TOKEN_COLON":
                                return True
                        return False
                i+=1
            return False
        return False

    def parse_lambda(self):
        children=[]
        # param
        if self.at("TOKEN_IDENT") and self.peek_kind(1)!="TOKEN_AT":
            # simple ident (could be colon next)
            ident_tok=self.bump()  # colon handled below? Need check: if next is colon, bump later
            ident_node=Node("NODE_IDENT",[ident_tok])
            children.append(ident_node)
            # expect colon
            self.expect("TOKEN_COLON","[TOKEN_COLON]")
        elif self.at("TOKEN_IDENT") and self.peek_kind(1)=="TOKEN_AT":
            # ident @ pattern
            bind_tok=self.bump(); at_tok=self.bump()
            pattern=self.parse_pattern()
            # wrap pattern with bind: mutate pattern to include bind tokens at front
            # pattern children: prepend Ident node and AT
            bind_node=Node("NODE_IDENT",[bind_tok])
            pattern.children = [bind_node, at_tok] + pattern.children
            # fix parents
            bind_node.parent=pattern
            pattern._bind_name = bind_tok.text  # dynamically set despite slots? Node has no such slot -> error. Use attribute via object.__setattr__? Node __slots__ prevents. We'll store in a dict side? Simpler: pattern bind detectable from children structure.
            children.append(pattern)
            self.expect("TOKEN_COLON","[TOKEN_COLON]")
        elif self.at("TOKEN_L_BRACE"):
            pattern=self.parse_pattern()
            children.append(pattern)
            # pattern may be followed by @ ident
            if self.at("TOKEN_AT"):
                at_tok=self.bump()
                # ident
                if self.at("TOKEN_IDENT"):
                    bind_tok=self.bump()
                    bind_node=Node("NODE_IDENT",[bind_tok])
                    pattern.children = pattern.children + [at_tok, bind_node]
                    bind_node.parent=pattern
                else:
                    # expect ident ... rnix wanted [TOKEN_IDENT]? For pattern bind after @ they expect ident; use expect
                    self.expect("TOKEN_IDENT","[TOKEN_IDENT]")
            self.expect("TOKEN_COLON","[TOKEN_COLON]")
        else:
            # shouldn't happen
            node=self.parse_primary()
            children.append(node)
            self.expect("TOKEN_COLON","[TOKEN_COLON]")
        body=self.parse_expr()
        children.append(body)
        return Node("NODE_LAMBDA", children)

    def parse_pattern(self):
        # assumes current is L_BRACE
        children=[]
        lb=self.bump(); children.append(lb)
        entries=[]
        ellipsis=False
        # loop entries
        while not self.at_eof() and not self.at("TOKEN_R_BRACE"):
            if self.at("TOKEN_ELLIPSIS"):
                et=self.bump(); children.append(et); ellipsis=True
                # after ellipsis, may have comma?
                if self.at("TOKEN_COMMA"):
                    children.append(self.bump())
                # continue (?) ellipsis should be last; loop will handle
                continue
            # pattern entry: name ident or string? parse key-ish
            entry_children=[]
            # name: ident or string or ??? rnix expects ident or ... Probe: pattern entry names can be strings? We'll accept IDENT/OR/STRING/dynamic
            if self.cur_kind() in ("TOKEN_IDENT","TOKEN_OR"):
                t=self.bump(); entry_children.append(Node("NODE_IDENT",[t]))
            elif self.at("TOKEN_STRING_START"):
                s=self.parse_string(); entry_children.append(s)
            elif self.at("TOKEN_INTERPOL_START"):
                d=self.parse_dynamic(); entry_children.append(d)
            else:
                # expect ident: rnix error for pattern entries: wanted [TOKEN_IDENT, TOKEN_OR] at entry start? For `{,}` etc pattern parse in attrset context differs. Use expect-like error for ident
                # Use expect TOKEN_IDENT with KEY_WANTED
                # But expect consumes recovery - okay
                self.expect("TOKEN_IDENT", KEY_WANTED)
                # break to avoid infinite loop
                # create empty entry
                entry=Node("NODE_PAT_ENTRY", entry_children)
                entries.append(entry); children.append(entry)
                if self.at("TOKEN_COMma".upper()):
                    pass
                # if next is comma bump?
                if self.at("TOKEN_COMMA"):
                    children.append(self.bump()); continue
                else:
                    break
                continue
            # optional default ? expr
            if self.at("TOKEN_QUESTION"):
                q=self.bump(); entry_children.append(q)
                # default expr: parse_expr (?) but must stop at comma / R_BRACE. parse_binop? RNix pattern default is an expression up to , or }. parse_expr will consume... a lambda body could consume }? parse_expr handles stops at commas because binop parsing doesn't consume comma. If default is attrset etc fine.
                default=self.parse_expr()
                entry_children.append(default)
            entry=Node("NODE_PAT_ENTRY", entry_children)
            entries.append(entry); children.append(entry)
            if self.at("TOKEN_COMMA"):
                children.append(self.bump()); continue
            else:
                break
        # closing brace
        # expect R_BRACE with no wanted (plain)
        if self.at("TOKEN_R_BRACE"):
            children.append(self.bump())
        else:
            self.expect("TOKEN_R_BRACE", None)
        node=Node("NODE_PATTERN", children)
        return node

    def parse_if(self):
        children=[]
        children.append(self.bump()) # if
        cond=self.parse_expr(); children.append(cond)
        self.expect("TOKEN_THEN","[TOKEN_THEN]")
        then_e=self.parse_expr(); children.append(then_e)
        self.expect("TOKEN_ELSE","[TOKEN_ELSE]")
        else_e=self.parse_expr(); children.append(else_e)
        return Node("NODE_IF_EXPR" if False else "NODE_IF", children)

    def parse_with(self):
        children=[self.bump()]
        env=self.parse_expr(); children.append(env)
        self.expect("TOKEN_SEMICOLON","[TOKEN_SEMICOLON]")
        body=self.parse_expr(); children.append(body)
        return Node("NODE_WITH", children)

    def parse_assert(self):
        children=[self.bump()]
        env=self.parse_expr(); children.append(env)
        self.expect("TOKEN_SEMICOLON","[TOKEN_SEMICOLON]")
        body=self.parse_expr(); children.append(body)
        return Node("NODE_ASSERT", children)

    def parse_let(self):
        children=[self.bump()] # let
        entries=[]
        # entries until IN
        while not self.at_eof() and not self.at("TOKEN_IN"):
            e=self.parse_entry_or_inherit()
            children.append(e)
            # if entry parsing consumed IN as recovery etc, loop checks
            # To prevent infinite loop, if no progress ... parse_entry should consume at least something or error
            if self.at("TOKEN_IN"):
                break
        # expect in: rnix expects IN with no wanted (plain eof)
        if self.at("TOKEN_IN"):
            children.append(self.bump())
        else:
            self.expect("TOKEN_IN", None)
        body=self.parse_expr(); children.append(body)
        return Node("NODE_LET_IN", children)

    def parse_legacy_let(self):
        children=[self.bump()] # let
        attr=self.parse_attrset(is_rec=False)
        children.append(attr)
        return Node("NODE_LEGACY_LET", children)

    def parse_entry_or_inherit(self):
        if self.at("TOKEN_INHERIT"):
            return self.parse_inherit()
        else:
            return self.parse_entry()

    def parse_inherit(self):
        children=[self.bump()] # inherit
        # optional ( expr )
        if self.at("TOKEN_L_PAREN"):
            children.append(self.bump())
            expr=self.parse_expr(); children.append(expr)
            # expect R_PAREN wanted [TOKEN_R_PAREN]
            self.expect("TOKEN_R_PAREN","[TOKEN_R_PAREN]")
            # after from, attrs
        # attrs: keys until semicolon
        while not self.at_eof() and not self.at("TOKEN_SEMICOLON"):
            # key could be ident/string/dynamic/or
            if self.cur_kind() in ("TOKEN_IDENT","TOKEN_OR"):
                t=self.bump(); key=Node("NODE_KEY",[Node("NODE_IDENT",[t])]); children.append(key)
            elif self.at("TOKEN_STRING_START"):
                s=self.parse_string(); key=Node("NODE_KEY",[s]); children.append(key)
            elif self.at("TOKEN_INTERPOL_START"):
                d=self.parse_dynamic(); key=Node("NODE_KEY",[d]); children.append(key)
            else:
                self.expect("TOKEN_IDENT", KEY_WANTED)
                break
        self.expect("TOKEN_SEMICOLON","[TOKEN_SEMICOLON]")
        return Node("NODE_INHERIT", children)

    def parse_entry(self):
        children=[]
        attrpath=self.parse_attrpath(); children.append(attrpath)
        self.expect("TOKEN_ASSIGN","[TOKEN_ASSIGN]")
        value=self.parse_expr(); children.append(value)
        self.expect("TOKEN_SEMICOLON","[TOKEN_SEMICOLON]")
        return Node("NODE_ENTRY", children)

    def parse_attrpath(self):
        children=[]
        key=self.parse_key(); children.append(key)
        while self.at("TOKEN_DOT"):
            children.append(self.bump())
            key=self.parse_key(); children.append(key)
        return Node("NODE_ATTRPATH", children)

    def parse_key(self):
        # returns NODE_KEY
        if self.cur_kind() in ("TOKEN_IDENT","TOKEN_OR"):
            t=self.bump(); ident=Node("NODE_IDENT",[t]); return Node("NODE_KEY",[ident])
        if self.at("TOKEN_STRING_START"):
            s=self.parse_string(); return Node("NODE_KEY",[s])
        if self.at("TOKEN_INTERPOL_START"):
            d=self.parse_dynamic(); return Node("NODE_KEY",[d])
        # error: expect ident
        # rnix: when expecting key, if EOF, error wanted [IDENT, OR] only (single). If token, error token wanted same and recovery as expect.
        # Use expect for TOKEN_IDENT with KEY_WANTED, but that will consume recovery and possibly create duplicate... For a.b. EOF case: expect IDENT at EOF gives one error. Good.
        # However expected token kind is IDENT but ??? If current token is e.g. R_BRACE, expect will consume it etc.
        # Create a dummy key node
        # Before calling expect, remember... expect will handle error recording.
        self.expect("TOKEN_IDENT", KEY_WANTED)
        # empty key node with range at current pos
        pos = self.cur().start if self.cur() else len(self.text)
        n=Node("NODE_KEY",[]); n._start=pos; n._end=pos; return n

    def parse_dynamic(self):
        # INTERPOL_START expr INTERPOL_END
        children=[self.bump()]
        expr=self.parse_expr(); children.append(expr)
        if self.at("TOKEN_INTERPOL_END"):
            children.append(self.bump())
        else:
            self.expect("TOKEN_INTERPOL_END", None)
        return Node("NODE_DYNAMIC", children)

    def parse_attrset(self, is_rec=False):
        children=[]
        if is_rec:
            children.append(self.bump()) # rec
        # expect L_BRACE
        if self.at("TOKEN_L_BRACE"):
            children.append(self.bump())
        else:
            self.expect("TOKEN_L_BRACE","[TOKEN_L_BRACE]")
            # if recovery failed and at EOF, return
        # entries until R_BRACE
        while not self.at_eof() and not self.at("TOKEN_R_BRACE"):
            e=self.parse_entry_or_inherit()
            children.append(e)
        if self.at("TOKEN_R_BRACE"):
            children.append(self.bump())
        else:
            self.expect("TOKEN_R_BRACE", None)
        kind="NODE_ATTR_SET"
        return Node(kind, children)

    # ---- binary / unary / apply / primary ----

    BIN_LEVELS = [
        # (ops set, associativity) from loosest to tightest in parsing order index
        ({"TOKEN_IMPLICATION"}, "right"),
        ({"TOKEN_OR_OR"}, "left"),
        ({"TOKEN_AND_AND"}, "left"),
        ({"TOKEN_EQUAL","TOKEN_NOT_EQUAL"}, "nonassoc"),
        ({"TOKEN_LESS","TOKEN_LESS_OR_EQ","TOKEN_MORE","TOKEN_MORE_OR_EQ"}, "nonassoc"),
        ({"TOKEN_UPDATE"}, "right"),
        # ! is handled as unary prefix before this level? We'll handle unary in parse_operand for levels: Actually parse_binop will call parse_unary at bottom.
        ({"TOKEN_ADD","TOKEN_SUB"}, "left"),
        ({"TOKEN_MUL","TOKEN_DIV"}, "left"),
        ({"TOKEN_CONCAT"}, "right"),
    ]

    def parse_binop(self, level=0):
        # level 0 is loosest (implication)
        if level >= len(self.BIN_LEVELS):
            return self.parse_unary_not()
        ops, assoc = self.BIN_LEVELS[level]
        lhs=self.parse_binop(level+1)
        # For right assoc: parse rhs at same level; for left/nonassoc: parse rhs at next level and loop
        if assoc=="right":
            if self.cur_kind() in ops:
                op_tok=self.bump()
                rhs=self.parse_binop(level)  # right
                node=Node("NODE_BIN_OP",[lhs,op_tok,rhs]); lhs.parent=node; rhs.parent=node; return node
            return lhs
        else:
            while self.cur_kind() in ops:
                op_kind=self.cur_kind()
                op_tok=self.bump()
                rhs=self.parse_binop(level+1)
                node=Node("NODE_BIN_OP",[lhs,op_tok,rhs]); lhs.parent=node; rhs.parent=node; lhs=node
                if assoc=="nonassoc":
                    break
            return lhs

    def parse_unary_not(self):
        # '!' prefix; operand is ... parse at level of add? Experiments show !x == true parses (!x)==true, and !a + b ? unknown. We'll parse operand as parse_binop from add level onward (i.e., tighter). Simpler: if !, operand = parse_unary_not recursively? That would make !x + y parse as !(x+y) if recursive returns parse_concat ... Need control.
        # Our chain: parse_binop(add level) calls parse_unary_not as its operand base (level beyond). So parse_unary_not should parse its operand using parse_apply/select (not full binop). That's tighter than add, so !a + b = (!a)+b.
        if self.at("TOKEN_INVERT"):
            op=self.bump()
            operand=self.parse_unary_not()
            node=Node("NODE_UNARY_OP",[op,operand]); operand.parent=node; return node
        return self.parse_apply()

    def parse_apply(self):
        # function application plus select/has etc handled in parse_select_chain for primaries.
        # Apply: sequence of select-expressions
        expr=self.parse_select_expr()
        while True:
            # an argument starts with primary starters / keyword? Arguments are select exprs, can be: primaries, lambda? identifiers etc, strings, numbers, lists, attrsets, paren, rec, - ?? Negation argument: f -1 ??? Nix argument can be `-1`? probe: `[ a -1 ]` errored because - is not element start, but f -x might parse as f (-x) or f - x... In apply parsing, after first, if next token can start a select value (incl STRING etc, IDENT, numbers, path) parse.
            if self._can_start_select_arg():
                arg=self.parse_select_expr()
                node=Node("NODE_APPLY",[expr,arg]); expr.parent=node; arg.parent=node; expr=node
            else:
                break
        return expr

    def _can_start_select_arg(self):
        k=self.cur_kind()
        if k in ("TOKEN_L_PAREN","TOKEN_REC","TOKEN_L_BRACE","TOKEN_L_BRACK","TOKEN_STRING_START","TOKEN_IDENT","TOKEN_INTEGER","TOKEN_FLOAT","TOKEN_PATH","TOKEN_URI"):
