                # parse as lambda argument
                return True
            if k=="TOKEN_L_BRACE" and self.is_lambda_start():
                return True
            return True
        return False

    def parse_select_expr(self):
        # parses a primary / value, then suffixes: .attrpath (select), ? attrpath (hasattr), also lambda if this position starts lambda (for arguments/list elements)
        if self.is_lambda_start():
            return self.parse_lambda()
        expr=self.parse_primary()
        # suffix loop
        while True:
            if self.at("TOKEN_DOT"):
                # select
                children=[expr, self.bump()]
                attrpath=self.parse_attrpath(); children.append(attrpath)
                # optional default: or expr_select
                if self.at("TOKEN_OR"):
                    # 'or' token: could be default
                    children.append(self.bump())
                    default=self.parse_select_expr(); children.append(default)
                node=Node("NODE_SELECT", children); expr.parent=node; attrpath.parent=node; expr=node; continue
            if self.at("TOKEN_QUESTION"):
                children=[expr, self.bump()]
                attrpath=self.parse_attrpath(); children.append(attrpath)
                node=Node("NODE_HAS_ATTR", children); expr.parent=node; attrpath.parent=node; expr=node; continue
            break
        return expr

    def parse_primary(self):
        k=self.cur_kind()
        if k is None:
            self.err_eof(None)
            n=Node("NODE_ERROR",[]); n._start=len(self.text); n._end=len(self.text); return n
        if k=="TOKEN_L_PAREN":
            children=[self.bump()]
            inner=self.parse_expr(); children.append(inner)
            if self.at("TOKEN_R_PAREN"):
                children.append(self.bump())
            else:
                self.expect("TOKEN_R_PAREN", None)
            node=Node("NODE_PAREN", children); inner.parent=node; return node
        if k=="TOKEN_REC":
            # rec attrset: rec expects {
            return self.parse_attrset(is_rec=True)
        if k=="TOKEN_L_BRACE":
            # attrset (lambda already handled higher)
            return self.parse_attrset(is_rec=False)
        if k=="TOKEN_L_BRACK":
            return self.parse_list()
        if k=="TOKEN_STRING_START":
            return self.parse_string()
        if k in ("TOKEN_IDENT",):
            t=self.bump(); return Node("NODE_IDENT",[t])
        if k in ("TOKEN_INTEGER","TOKEN_FLOAT","TOKEN_URI","TOKEN_PATH"):
            t=self.bump()
