                        interp_children=[self.bump()]
                        e=self.parse_expr(); interp_children.append(e)
                        if self.at("TOKEN_INTERPOL_END"):
                            interp_children.append(self.bump())
                        else:
                            self.expect("TOKEN_INTERPOL_END",None)
