def parse_source(text):
    p=Parser(text)
    root=p.parse_root()
    # set parents recursively (Node init already for children passed, but mutated children need fix)
    def fix(node):
        for ch in node.children:
            if isinstance(ch, Node):
                ch.parent=node; fix(ch)
    fix(root)
    root.parent=None
    return root, p.errors

