            if self.i>=self.n:
                ln,cl=self.line_col(self.i)
                raise ConfigError(f"unable to parse config file: unexpected eof encountered at line {ln} column {cl}")
            if self.peek()==',':
                self.i+=1; continue
            if self.peek()==']':
                self.i+=1; break
            # expected a right bracket, found X - position of next token; original fuzz: [1 2] found identifier at position of 2
            self.err_expected("a right bracket", self.token_desc_at(self.i), self.i)
        return TomlValue("sequence", elements, line, col)
    def parse_inline_table(self):
        start=self.i; line,col=self.line_col(start)
        self.i+=1 # {
        entries={}
        while True:
            self.skip_spaces_tabs()
            if self.i>=self.n:
                self.err_expected("a table key", "eof", self.i)
            if self.peek()=='}':
                self.i+=1; break
            # key
            kp=self.parse_key_path_str()
            self.skip_spaces_tabs()
            if self.peek()!='=':
                self.err_expected("an equals", self.token_desc_at(self.i) if self.i<self.n else "eof", self.i)
            self.i+=1; self.skip_spaces_tabs()
            val=self.parse_value(); entries[kp]=val
            self.skip_spaces_tabs()
            if self.peek()==',':
                self.i+=1; continue
            if self.peek()=='}':
                self.i+=1; break
            # expected a comma
            if self.i>=self.n:
                self.err_expected("a comma", "eof", self.i)
            self.err_expected("a comma", self.token_desc_at(self.i), self.i)
        return TomlValue("table", entries, line, col)

def type_name_for_error(val):
    if val.kind=="integer": return f"integer `{val.value}`"
    if val.kind=="float": return f"floating point `{repr(val.value)}`"
    if val.kind=="boolean": return "boolean `true`" if val.value else "boolean `false`"
    if val.kind=="string": return f'string "{val.value}"'
    if val.kind=="sequence": return "sequence"
    if val.kind=="table": return "map"
    if val.kind=="datetime": return "datetime string"
    return val.kind

def config_from_toml_text(text):
    parser=TomlParser(text)
    fields=parser.parse()
    disabled=[]; ignore=[]
    for key in ("disabled","ignore"):
        if key in fields:
            val=fields[key]
            if val.kind!="sequence":
                raise ConfigError(f"unable to parse config file: invalid type: {type_name_for_error(val)}, expected a sequence for key `{key}` at line {val.line} column {val.col}")
            lst=[]
            for el in val.value:
                if el.kind!="string":
                    # position: for nested sequence, original reports line1 col1 odd; if kind sequence/table, use 1,1
                    if el.kind in ("sequence","table"):
                        ln,cl=1,1
                    else:
                        ln,cl=el.line, el.col
                    raise ConfigError(f"unable to parse config file: invalid type: {type_name_for_error(el)}, expected a string for key `{key}` at line {ln} column {cl}")
                lst.append(el.value)
            if key=="disabled": disabled=lst
            else: ignore=lst
    return disabled, ignore

def read_config_file(path):
    # raises ConfigError with prefix content (without "config error: ")
    try:
        with open(path,'rb') as f:
            data=f.read()
    except OSError as e:
        raise ConfigError(f"path error: {io_error_str(e)}")
    try:
        text=data.decode('utf-8')
    except UnicodeDecodeError:
        # guess: rust read_to_string would error "stream did not contain valid UTF-8"? wrapped as path error? We'll use that text
        raise ConfigError(f"path error: stream did not contain valid UTF-8")
    return config_from_toml_text(text)

def load_config(conf_path):
    # conf_path string
    if os.path.isdir(conf_path):
        joined=os.path.join(conf_path, "statix.toml")
        if not os.path.lexists(joined):
            return [], []
        return read_config_file(joined)
    else:
        return read_config_file(conf_path)

