def glob_to_regex(pat):
    # Translate globset-like glob to regex string (full match)
    i=0; n=len(pat); out=""
    while i<n:
        c=pat[i]
        if c=='*':
            if i+1<n and pat[i+1]=='*':
                # ** handling
                j=i
                while j<n and pat[j]=='*': j+=1
                count=j-i
                # if ** is a full component (/**/, leading **/, trailing /**, or whole **)
                # globset: ** matches any number of chars including /
                # We'll translate to .* (with care for /**/ -> match zero or more dirs)
                # Detect patterns:
                if pat[i:j]=="**":
                    # check surroundings in original
                    before = pat[i-1] if i>0 else ''
                    after = pat[j] if j<n else ''
                    if before=='/' and after=='/':
                        # /**/ -> /(?:.*/)?   (our out already has '/' from before? We consumed before as literal '/' in previous iteration, so need handle specially)
                        # Since before already appended as '/', we can append (?:.*/)?
                        # Simpler: We'll handle /**/ at slash processing point below; this branch only for standalone **
                        out+="(?:.*)?"
                    else:
                        out+=".*"
                    i=j; continue
                else:
                    # e.g. *** treated as **? globset allows... translate to .*
                    out+=".*"; i=j; continue
            else:
                out+="[^/]*"; i+=1; continue
        elif c=='?':
            out+="[^/]"; i+=1; continue
        elif c=='[':
            # character class
            j=i+1
            if j<n and pat[j] in ('!','^'):
                # globset: [!...] is negation? In glob crate, ! is negation. Its error messages suggest [! ] works. We'll support ! as negation, ^ literal.
                neg=False
                if pat[j]=='!':
                    neg=True; j+=1
                # collect
                start=j
                if j<n and pat[j]==']': j+=1
                while j<n and pat[j]!=']':
                    j+=1
                if j>=n:
                    raise ValueError("unclosed character class")
                inner=pat[start:j]
                # escape regex specials but keep ranges
                inner_esc=inner.replace('\\','\\\\')
                out+="["+("^" if neg else "")+inner_esc+"]"
                i=j+1; continue
            else:
                start=j
                if j<n and pat[j]==']': j+=1
                while j<n and pat[j]!=']':
                    j+=1
                if j>=n:
                    raise ValueError("unclosed character class")
                inner=pat[start:j]
                inner_esc=inner.replace('\\','\\\\')
                out+="["+inner_esc+"]"
                i=j+1; continue
        elif c=='{':
            # alternates
            j=i+1; depth=1; alts=[]; cur=""
            while j<n and depth>0:
                ch=pat[j]
                if ch=='{': depth+=1; cur+=ch
                elif ch=='}':
                    depth-=1
                    if depth==0: break
                    cur+=ch
                elif ch==',' and depth==1:
                    alts.append(cur); cur=""
                else:
                    cur+=ch
                j+=1
            if j>=n:
                raise ValueError("unclosed alternate")
            alts.append(cur)
            parts=[]
            for alt in alts:
                parts.append(glob_to_regex(alt))
            out+="(?:"+ "|".join(parts) +")"
            i=j+1; continue
        elif c=='\\' and i+1<n:
            out+=re.escape(pat[i+1]); i+=2; continue
        elif c=='/' and pat[i:i+4]=='/**/':
            # match zero or more directories
            out+="/(?:.*/)?"
            i+=4; continue
        else:
            out+=re.escape(c); i+=1; continue
    return out

class GlobPattern:
    __slots__=("original","regex","negated","dir_only","anchored")
    def __init__(self, original, regex, negated, dir_only):
        self.original=original; self.regex=re.compile("^"+regex+"$") if regex is not None else None; self.negated=negated; self.dir_only=dir_only
    def matches(self, rel_path, is_dir):
        if self.dir_only and not is_dir:
            # gitignore dir-only patterns don't match files directly (our walker prunes dirs)
            return False
        if self.regex is None:
            return False
        return bool(self.regex.match(rel_path))

def validate_globset(pat):
    # Return error string in globset format if invalid, else None
    # Check unclosed class/alternate, dangling \, invalid range.
    i=0; n=len(pat)
    while i<n:
        c=pat[i]
        if c=='\\':
            if i+1>=n:
                return f"error parsing glob '{pat}': dangling '\\'"
            i+=2; continue
        if c=='[':
            j=i+1
            if j<n and pat[j]=='!': j+=1
            if j<n and pat[j]==']': j+=1
            found=False
            prev=None
            while j<n:
                if pat[j]=='\\' and j+1<n:
                    j+=2; continue
                if pat[j]==']':
                    found=True; break
                if pat[j]=='-' and prev is not None and j+1<n and pat[j+1]!=']':
                    nxt=pat[j+1]
                    if ord(prev)>ord(nxt):
                        return f"error parsing glob '{pat}': invalid range; '{prev}' > '{nxt}'"
                prev=pat[j]; j+=1
            if not found:
                return f"error parsing glob '{pat}': unclosed character class; missing ']'"
            i=j+1; continue
        if c=='{':
            # find closing
            depth=1; j=i+1; found=False
            while j<n:
                if pat[j]=='{': depth+=1
                elif pat[j]=='}':
                    depth-=1
                    if depth==0: found=True; break
                j+=1
            if not found:
                return f"error parsing glob '{pat}': unclosed alternate group; missing '}}' (maybe escape '{{' with '[{{]'?)"
            i=j+1; continue
        i+=1
    return None

def parse_gitignore_line(line, original_for_error=None, raise_on_error=False):
    # Returns GlobPattern or None (comment/empty/invalid if not raise)
    # gitignore line syntax:
    orig=line
    # Trailing spaces are ignored unless escaped with backslash; our walker file lines have newline removed.
    # Remove trailing unescaped spaces/tabs? gitignore trims trailing spaces. For CLI pattern with trailing space (?), earlier 'a.nix ' as CLI matched with trailing space? It excluded a (in tr10 test, 'a.nix ' ignored a). Gitignore line would trim trailing space, so matches.
    # Leading spaces: not trimmed (literal)
    s=line
    # Strip trailing spaces that are not escaped
    # Count trailing spaces
    end=len(s)
    while end>0 and s[end-1] in ' \t':
        # check if escaped by an odd number of backslashes before
        bs=0; k=end-2
        while k>=0 and s[k]=='\\': bs+=1; k-=1
        if bs%2==1:
            break
        end-=1
    s=s[:end]
    if s.strip()=="":
        return None
    if s.startswith('#'):
        return None
    negated=False
    if s.startswith('!'):
        negated=True; s=s[1:]
    elif s.startswith('\\!') or s.startswith('\\#'):
        s=s[1:]  # literal ! or #
    if s=="":
        return None
    dir_only=False
    if s.endswith('/'):
        dir_only=True; s=s[:-1]
        if s=="":
            return None
    anchored=False
    if s.startswith('/'):
        anchored=True; s=s[1:]
        if s=="":
            return None
    elif '/' in s:
        anchored=True
    # validate globset on the pattern transformed? The glob that error refers to is original 's' before transformation but after gitignore stripping? Original errors for CLI '[a-' were that string. For dir pattern etc, validation on s.
    # If escaped chars etc, globset validation above handles.
    err=validate_globset(s)
    if err:
        if raise_on_error:
            # original_for_error is full original input string (not stripped)
            raise ConfigError(f"error parsing ignore list `error parsing glob '{original_for_error}': {err.split(': ',1)[1] if ': ' in err else err}`")
            # The nested message needs exact: err already is "error parsing glob '{pat}': {msg}" but for original it uses the raw pattern given. We'll construct below outside.
        return None
    # transformation
    if anchored:
        actual=s
    else:
        actual="**/"+s
    # dir_only: actual matches directory itself; walker handles file pruning.
    try:
        regex_str=glob_to_regex(actual)
        rx=re.compile("^"+regex_str+"$")
    except Exception:
        if raise_on_error:
            raise
        return None
    pat=GlobPattern(orig, regex_str, negated, dir_only)
    pat.regex=rx
    return pat

def compile_ignore_pattern(raw):
    # CLI/config pattern: validate with globset error naming raw
    # gitignore parsing will strip etc. But if error, message uses raw as given.
    # Need check invalid before stripping neg etc: validate_globset on the glob portion? Original for '[a-' matched; for '! [a-' ... unknown. We'll validate on stripped core if parse would...
    # Approach: try to parse but detect invalid glob portion manually:
    # Determine core s after gitignore stripping (leading ! etc)
    s=raw
    # comment pattern: #... no glob error
    if s.startswith('#'):
        return None
    if s.startswith('!'): s_core=s[1:]
    elif s.startswith('\\!'): s_core=s[1:]
    else: s_core=s
    # trailing slash removal for dir_only
    core_for_validate=s_core.rstrip()
    if core_for_validate.endswith('/'): core_for_validate=core_for_validate[:-1]
    if core_for_validate.startswith('/'): core_for_validate=core_for_validate[1:]
    err=validate_globset(core_for_validate) if core_for_validate!="" else None
    if err:
        # extract msg after ": "
        # validate_globset returns f"error parsing glob '{pat}': {msg}"
        msg=err.split("': ",1)
        msg_text=msg[1] if len(msg)>1 else err
        raise ConfigError(f"error parsing ignore list `error parsing glob '{raw}': {msg_text}`")
    return parse_gitignore_line(raw)

class IgnoreMatcher:
    def __init__(self):
        self.patterns=[]  # list of GlobPattern in order
    def add_patterns_from_gitignore_file(self, path):
        try:
            with open(path,'r',encoding='utf-8',errors='ignore') as f:
                text=f.read()
        except OSError:
            return
        for line in text.splitlines():
            try:
                pat=parse_gitignore_line(line)
            except Exception:
                pat=None
            if pat is not None:
                self.patterns.append(pat)
    def add_raw_pattern(self, raw):
        pat=compile_ignore_pattern(raw)
        if pat is not None:
            self.patterns.append(pat)
    def is_ignored(self, rel_path, is_dir):
        # rel_path uses / separators, no leading ./
        result=False
        for pat in self.patterns:
            # For dir-only patterns: matches directories only
            if pat.dir_only and not is_dir:
                continue
            if pat.regex and pat.regex.match(rel_path):
                result=not pat.negated
            else:
                # Also pattern may match a parent directory for files ? If pat matches any ancestor dir, file is ignored unless negation re-includes a parent... Our walker prunes dirs, but if we evaluate file directly (e.g., root check?) handle:
                # Check ancestors
                if not is_dir:
                    parts=rel_path.split('/')
                    for i in range(1,len(parts)):
                        ancestor="/".join(parts[:i])
                        # dir patterns and non-dir patterns that match a directory name should ignore contents (per git, if pattern matches directory, contents ignored)
                        # Only if pat is not ??? We'll apply when pat matches ancestor as a dir:
                        if pat.regex and pat.regex.match(ancestor):
                            result=not pat.negated; break
        return result

