class ConfigError(Exception):
    pass

def io_error_str(e):
    # e is OSError
    return f"{e.strerror} (os error {e.errno})"

class TomlValue:
    __slots__=("kind","value","line","col")
    def __init__(self, kind, value, line, col):
        self.kind=kind; self.value=value; self.line=line; self.col=col

class TomlParser:
    def __init__(self, text):
        self.text=text; self.i=0; self.n=len(text)
    def line_col(self, pos=None):
        if pos is None: pos=self.i
        if pos>self.n: pos=self.n
        line=self.text.count("\n",0,pos)+1
        last=self.text.rfind("\n",0,pos)
        col=pos-last if last!=-1 else pos+1
        # column: 1-indexed; if last newline at pos-1, col = pos-last =? Example EOF after newline gives col1, okay
        return line, col
    def err_expected(self, expected, found_desc, pos):
        line,col=self.line_col(pos)
        raise ConfigError(f"unable to parse config file: expected {expected}, found {found_desc} at line {line} column {col}")
    def err_msg(self, msg, pos=None):
        line,col=self.line_col(pos)
        raise ConfigError(f"unable to parse config file: {msg} at line {line} column {col}")
    def peek(self):
        return self.text[self.i] if self.i<self.n else ""
    def skip_spaces_tabs(self):
        while self.i<self.n and self.text[self.i] in ' \t':
            self.i+=1
    def skip_ws_comments_newlines(self):
        while self.i<self.n:
            c=self.text[self.i]
            if c in ' \t\r\n':
                self.i+=1
            elif c=='#':
                # to newline
                j=self.text.find('\n', self.i)
                self.i=self.n if j==-1 else j
            else:
                break
    def token_desc_at(self, pos):
        if pos>=self.n: return "eof"
        c=self.text[pos]
        if c=='\n': return "a newline"
        if c=='[': return "a left bracket"
        if c==']': return "a right bracket"
        if c=='{': return "a left brace"
        if c=='}': return "a right brace"
        if c=='=': return "an equals"
        if c==',': return "a comma"
        if c=='.': return "a period"
        if c==':': return "a colon"
        # identifier-ish (bare value/key chars)
        return "an identifier"
    def parse(self):
        # returns dict root with path tracking: we only need root fields disabled/ignore and their TomlValues
        root_fields={}
        seen_root_fields=set()
        tables_defined=set()
        current_table=""  # "" for root
        # For duplicate known field detection at root
        while True:
            self.skip_spaces_tabs()
            # comments
            if self.peek()=='#':
                # skip to eol
                while self.i<self.n and self.text[self.i]!='\n': self.i+=1
            if self.i>=self.n:
                break
            if self.peek()=='\n' or self.peek()=='\r':
                self.i+=1; continue
            if self.peek()=='[':
                # table header
                header_start=self.i
                is_array=False
                self.i+=1
                if self.peek()=='[':
                    is_array=True; self.i+=1
                self.skip_spaces_tabs()
                # key path until ]
                table_name=self.parse_key_path_str(for_header=True)
                self.skip_spaces_tabs()
                if self.i>=self.n:
                    self.err_expected("a right bracket", "eof", self.i)
                if self.peek()!=']':
                    self.err_expected("a right bracket", self.token_desc_at(self.i), self.i)
                self.i+=1
                if is_array:
                    if self.peek()==']': self.i+=1
                    else: self.err_expected("a right bracket", self.token_desc_at(self.i), self.i)
                # redefinition check for non-array tables
                if not is_array:
                    if table_name in tables_defined:
                        line,col=self.line_col(header_start)
                        raise ConfigError(f"unable to parse config file: redefinition of table `{table_name}` for key `{table_name}` at line {line} column {col}")
                    tables_defined.add(table_name)
                current_table=table_name
                # expect newline/eof/comment
                self.expect_newline_or_eof()
                continue
            # key = value
            key_start=self.i
            # parse key path
            key_path=self.parse_key_path_str()
            self.skip_spaces_tabs()
            if self.i>=self.n:
                self.err_expected("an equals", "eof", self.i)
            if self.peek()!='=':
                self.err_expected("an equals", self.token_desc_at(self.i), self.i)
            self.i+=1
            self.skip_spaces_tabs()
            val=self.parse_value()
            # expect newline
            self.expect_newline_or_eof(in_value=False)
            if current_table=="":
                # root field: only first segment? If key_path has dots, serde struct field is ??? Only exact "disabled"/"ignore" as single key matters.
                if key_path in ("disabled","ignore"):
                    if key_path in seen_root_fields:
                        raise ConfigError(f"unable to parse config file: duplicate field `{key_path}` at line 1 column 1")
                    seen_root_fields.add(key_path)
                    root_fields[key_path]=val
                else:
                    # unknown root field; serde ignores, duplicates ignored
                    pass
            # else ignore
        return root_fields
    def expect_newline_or_eof(self, in_value=False):
        self.skip_spaces_tabs()
        if self.peek()=='#':
            while self.i<self.n and self.text[self.i]!='\n': self.i+=1
        if self.i>=self.n:
            return
        if self.peek()=='\n':
            self.i+=1; return
        if self.peek()=='\r':
            # handle \r\n
            self.i+=1
            if self.peek()=='\n': self.i+=1
            return
        # found something
        self.err_expected("newline", self.token_desc_at(self.i), self.i)
    def parse_key_path_str(self, for_header=False):
        parts=[]
        while True:
            self.skip_spaces_tabs()
            part=self.parse_key_part()
            parts.append(part)
            self.skip_spaces_tabs()
            if self.peek()=='.':
                self.i+=1; continue
            break
        return ".".join(parts)
    def parse_key_part(self):
        if self.i>=self.n:
            self.err_expected("a table key", "eof", self.i)
        c=self.peek()
        if c=='"' or c=="'":
            val=self.parse_string()
            return val.value
        # bare key chars
        start=self.i
        while self.i<self.n and (self.text[self.i].isalnum() or self.text[self.i] in '_-'):
            self.i+=1
        if self.i==start:
            self.err_expected("a table key", self.token_desc_at(self.i), self.i)
        return self.text[start:self.i]
    def parse_value(self):
        if self.i>=self.n:
            # unexpected eof encountered (used for x= at EOF, array EOF handled separately)
            line,col=self.line_col(self.i)
            raise ConfigError(f"unable to parse config file: unexpected eof encountered at line {line} column {col}")
        c=self.peek()
        if c=='\n':
            self.err_expected("a value", "a newline", self.i)
        if c=='=':
            # expected a value, found an equals - position: toml crate reported column 3 for x==1 (the first equals sign itself as delimiter? our cursor is at second '='; original column 3 is first???? In x==1, keys x(1) space? string "x==1": col1 x, col2 =, col3 =. They reported found an equals at col3 = second equals. Good cursor points there.
            self.err_expected("a value", "an equals", self.i)
        if c=='"' or c=="'":
            return self.parse_string()
        if c=='[':
            return self.parse_array()
        if c=='{':
            return self.parse_inline_table()
        # bare token: bool, number, date, identifier-as-error? TOML bare values other than true/false/numbers/dates are invalid: toml crate would error "expected a value, found ..." ? e.g. a=\n etc. Backslash case:
        if c=='\\':
            line,col=self.line_col(self.i)
            raise ConfigError(f"unable to parse config file: unexpected character found: `\\` at line {line} column {col}")
        start=self.i
        # consume until delimiter: newline, comma, ], }, #, space
        while self.i<self.n and self.text[self.i] not in '\n,]}# \t\r':
            self.i+=1
        token=self.text[start:self.i]
        line,col=self.line_col(start)
        if token in ("true","false"):
            return TomlValue("boolean", token=="true", line, col)
        # numbers
        # integer with underscores etc
        t_clean=token.replace("_","")
        try:
            # hex/oct/bin
            if t_clean.lower().startswith(("0x",)):
                return TomlValue("integer", int(t_clean,16), line, col)
            if t_clean.lower().startswith(("0o",)):
                return TomlValue("integer", int(t_clean,8), line, col)
            if t_clean.lower().startswith(("0b",)):
                return TomlValue("integer", int(t_clean,2), line, col)
            if re.fullmatch(r'[+-]?[0-9]+', t_clean):
                return TomlValue("integer", int(t_clean), line, col)
            if re.fullmatch(r'[+-]?([0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)([eE][+-]?[0-9]+)?', t_clean) and any(ch in t_clean for ch in '.eE'):
