    return f"{e.strerror} (os error {e.errno})"

class TomlValue:
    __slots__=("kind","value","line","col")
    def __init__(self, kind, value, line, col):
        self.kind=kind; self.value=value; self.line=line; self.col=col

class TomlParser:
    def __init__(self, text):
        self.text=text; self.i=0; self.n=len(text)
    def line_col(self, pos=None):
        if pos is None: pos=self.i
        if pos>self.n: pos=self.n
        line=self.text.count("\n",0,pos)+1
        last=self.text.rfind("\n",0,pos)
        col=pos-last if last!=-1 else pos+1
        # column: 1-indexed; if last newline at pos-1, col = pos-last =? Example EOF after newline gives col1, okay
        return line, col
    def err_expected(self, expected, found_desc, pos):
        line,col=self.line_col(pos)
        raise ConfigError(f"unable to parse config file: expected {expected}, found {found_desc} at line {line} column {col}")
    def err_msg(self, msg, pos=None):
        line,col=self.line_col(pos)
        raise ConfigError(f"unable to parse config file: {msg} at line {line} column {col}")
    def peek(self):
        return self.text[self.i] if self.i<self.n else ""
    def skip_spaces_tabs(self):
        while self.i<self.n and self.text[self.i] in ' \t':
            self.i+=1
    def skip_ws_comments_newlines(self):
        while self.i<self.n:
            c=self.text[self.i]
            if c in ' \t\r\n':
                self.i+=1
            elif c=='#':
                # to newline
                j=self.text.find('\n', self.i)
                self.i=self.n if j==-1 else j
            else:
                break
    def token_desc_at(self, pos):
        if pos>=self.n: return "eof"
        c=self.text[pos]
        if c=='\n': return "a newline"
        if c=='[': return "a left bracket"
        if c==']': return "a right bracket"
        if c=='{': return "a left brace"
        if c=='}': return "a right brace"
        if c=='=': return "an equals"
        if c==',': return "a comma"
        if c=='.': return "a period"
        if c==':': return "a colon"
        # identifier-ish (bare value/key chars)
        return "an identifier"
    def parse(self):
        # returns dict root with path tracking: we only need root fields disabled/ignore and their TomlValues
        root_fields={}
        seen_root_fields=set()
        tables_defined=set()
        current_table=""  # "" for root
        # For duplicate known field detection at root
        while True:
            self.skip_spaces_tabs()
            # comments
            if self.peek()=='#':
                # skip to eol
                while self.i<self.n and self.text[self.i]!='\n': self.i+=1
            if self.i>=self.n:
                break
            if self.peek()=='\n' or self.peek()=='\r':
                self.i+=1; continue
            if self.peek()=='[':
                # table header
                header_start=self.i
                is_array=False
                self.i+=1
                if self.peek()=='[':
                    is_array=True; self.i+=1
                self.skip_spaces_tabs()
                # key path until ]
                table_name=self.parse_key_path_str(for_header=True)
                self.skip_spaces_tabs()
                if self.i>=self.n:
                    self.err_expected("a right bracket", "eof", self.i)
                if self.peek()!=']':
                    self.err_expected("a right bracket", self.token_desc_at(self.i), self.i)
                self.i+=1
                if is_array:
                    if self.peek()==']': self.i+=1
                    else: self.err_expected("a right bracket", self.token_desc_at(self.i), self.i)
                # redefinition check for non-array tables
                if not is_array:
                    if table_name in tables_defined:
                        line,col=self.line_col(header_start)
                        raise ConfigError(f"unable to parse config file: redefinition of table `{table_name}` for key `{table_name}` at line {line} column {col}")
                    tables_defined.add(table_name)
                current_table=table_name
