        panic(panic_location, 'called `Result::unwrap()` on an `Err` value: Error { kind: InvalidData, message: "stream did not contain valid UTF-8" }')

def file_extension_is_nix(path_str):
    base=os.path.basename(path_str)
    dot=base.rfind('.')
    if dot<=0:
        return False
    ext=base[dot+1:]
    return ext=="nix"

class LoadedFile:
    __slots__=("display","source","write_path")
    def __init__(self, display, source, write_path):
        self.display=display; self.source=source; self.write_path=write_path

def read_loaded(display):
    try:
        with open(display,'rb') as f:
            data=f.read()
    except OSError:
        return LoadedFile(display, None, display)
    try:
        text=data.decode('utf-8')
    except UnicodeDecodeError:
        return LoadedFile(display, None, display)
    return LoadedFile(display, text, display)

def build_matcher(target, unrestricted, cli_ignore, cfg_ignore):
    matcher=IgnoreMatcher()
    if not unrestricted:
        gitignore_path=os.path.join(target, ".gitignore")
        matcher.add_patterns_from_gitignore_file(gitignore_path)
    for pat in cli_ignore:
        matcher.add_raw_pattern(pat)
    for pat in cfg_ignore:
        matcher.add_raw_pattern(pat)
    return matcher

def walk_dir(root_display, matcher, results):
    try:
        entries=list(os.scandir(root_display))
    except OSError:
        return
    for entry in entries:
        name=entry.name
        display=os.path.join(root_display, name)
        try:
            is_dir=entry.is_dir(follow_symlinks=True)
        except OSError:
            is_dir=False
        # relative path for matcher
        try:
            rel=os.path.relpath(display, root_display if False else walk_dir.root)
        except Exception:
            rel=name
        rel=rel.replace(os.sep,'/')
        if is_dir:
            if name==".git":
                continue
            if matcher is not None and matcher.is_ignored(rel, True):
                continue
            walk_dir(display, matcher, results)
        else:
            try:
                is_file=entry.is_file(follow_symlinks=True)
            except OSError:
                is_file=False
            if not is_file:
                continue
            if not file_extension_is_nix(name):
                continue
            if matcher is not None and matcher.is_ignored(rel, False):
                continue
            results.append(read_loaded(display))

def load_files(target, matcher):
    # existence check: Rust Path::exists follows links
    if not os.path.exists(target):
        raise ConfigError(f"path error: file not found: {target}")
    if os.path.isfile(target):
        if not file_extension_is_nix(target):
            return []
        return [read_loaded(target)]
    if os.path.isdir(target):
        results=[]
        walk_dir.root=target
        walk_dir(target, matcher, results)
        return results
    return []

def print_reports_for_file(path, source, reports, fmt):
    if fmt=="errfmt":
        sys.stdout.write(format_errfmt(path, source, reports))
    else:
        for rep in reports:
            try:
                rendered=render_report(path, source, rep)
            except AriadnePanic as e:
                header=getattr(e,'header','')
                if header:
                    sys.stdout.write(header); sys.stdout.flush()
                panic(PANIC_ARIADNE, "index out of bounds: the len is 0 but the index is 0")
            sys.stdout.write(rendered)

def missing_required(cmd, items):
    lst="".join(f"    {it}\n" for it in items)
    return ClapExit(f"error: The following required arguments were not provided:\n{lst}\nUSAGE:\n    {fmt_usage(cmd)}\n\nFor more information try --help\n",2)

def ensure_no_extra(cmd, positionals, allowed):
    if len(positionals)>allowed:
        raise clap_error_found_arg(positionals[allowed], cmd)

def do_check(cmd, values, positionals):
    # validate format
    fmt="stderr"
    if "format" in values:
        status, res = validate_format(values["format"])
        if status=="error":
            raise ClapExit(f"error: Invalid value for '--format <FORMAT>': {res}\n\nFor more information try --help\n",2)
        fmt=res
    ensure_no_extra(cmd, positionals, 1)
    target=positionals[0] if positionals else "."
    conf_path=values.get("config",".")
    stdin_flag=bool(values.get("stdin",False))
    # config file first
    disabled, cfg_ignore = load_config(conf_path)
    if stdin_flag:
        source=read_stdin_text(PANIC_STDIN_CHECK)
        reports,_,_errors = analyze(source, disabled)
        if reports:
            print_reports_for_file("<stdin>", source, reports, fmt)
            return 1
        return 0
    cli_ignore=values.get("ignore",[])
    if isinstance(cli_ignore, str): cli_ignore=[cli_ignore]
    matcher=build_matcher(target, bool(values.get("unrestricted",False)), cli_ignore, cfg_ignore)
    files=load_files(target, matcher)
    any_reports=False
    for lf in files:
        if lf.source is None:
            sys.stdout.write(f"`{lf.display}` contains non-utf8 content\n"); continue
        reports,_,_ = analyze(lf.source, disabled)
        if reports:
            any_reports=True
            print_reports_for_file(lf.display, lf.source, reports, fmt)
    return 1 if any_reports else 0

def do_fix(cmd, values, positionals):
    ensure_no_extra(cmd, positionals, 1)
    target=positionals[0] if positionals else "."
    conf_path=values.get("config",".")
    stdin_flag=bool(values.get("stdin",False))
    dry=bool(values.get("dry-run",False))
    disabled, cfg_ignore = load_config(conf_path)
    if stdin_flag:
        source=read_stdin_text(PANIC_STDIN_FIX)
        fixed=make_fixed(source, disabled)
        if dry:
            diff=unified_diff(source, fixed, "<stdin>")
            sys.stdout.write(diff+"\n" if diff else "\n")
        else:
            sys.stdout.write(fixed)
        return 0
    cli_ignore=values.get("ignore",[])
    if isinstance(cli_ignore, str): cli_ignore=[cli_ignore]
    matcher=build_matcher(target, bool(values.get("unrestricted",False)), cli_ignore, cfg_ignore)
    files=load_files(target, matcher)
    for lf in files:
        if lf.source is None:
            sys.stdout.write(f"`{lf.display}` contains non-utf8 content\n"); continue
        fixed=make_fixed(lf.source, disabled)
        if dry:
            diff=unified_diff(lf.source, fixed, lf.display)
            sys.stdout.write(diff+"\n" if diff else "\n")
        else:
            if fixed!=lf.source:
                try:
                    with open(lf.write_path,'w',encoding='utf-8',newline='') as f:
                        f.write(fixed)
                except OSError:
                    pass
    return 0

def position_to_offset(source, line, col):
    # Rust-like lines: split by lines()
    # lines() in Rust: if source ends with \n, no trailing empty line; empty source -> no lines
    if source=="":
        lines=[]
    else:
        lines=source.split("\n")
        if source.endswith("\n"):
            lines=lines[:-1]
    line_idx=0 if line==0 else line-1
    if line_idx<0 or line_idx>=len(lines):
        return None
    line_text=lines[line_idx]
    # col is byte offset within line (empirically)
    line_bytes=line_text.encode('utf-8')
    if col>len(line_bytes):
        return None
    # offset in chars: byte offset to char index
    byte_offset=sum(len(lines[i].encode('utf-8'))+1 for i in range(line_idx)) + col
    # convert global byte offset to char index
    # if col falls inside a utf8 char, Rust code might slice panic; we treat as: decode up to byte offset with errors? Use bytes of source
    src_bytes=source.encode('utf-8')
    if byte_offset>len(src_bytes):
        return None
    try:
        return len(src_bytes[:byte_offset].decode('utf-8'))
    except UnicodeDecodeError:
        return None

def single_attempt(source, line, col):
    # returns (status, result) status: 'fixed','nothing','oob'
    offset=position_to_offset(source, line, col)
    if offset is None:
        return ("oob", source)
    reports,_,errors=analyze(source, [])
    if errors:
        return ("nothing", source)
    for rep in reports:
        if rep.suggestion is None: continue
        for d in rep.diags:
            if d.start <= offset < d.end or (d.start==d.end==offset):
                return ("fixed", apply_suggestion(source, rep.suggestion))
    return ("nothing", source)

def do_single(cmd, values, positionals):
    # required position check is handled before call
    ensure_no_extra(cmd, positionals, 1)
    target=positionals[0] if positionals else None
    stdin_flag=bool(values.get("stdin",False))
    dry=bool(values.get("dry-run",False))
    pos=values["_position_parsed"]
    line,col=pos
    if not stdin_flag and target is None:
        panic(PANIC_SINGLE_NO_TARGET, "called `Option::unwrap()` on a `None` value")
    if stdin_flag:
        source=read_stdin_text(PANIC_STDIN_SINGLE)
        status, result = single_attempt(source, line, col)
        if dry:
            diff=unified_diff(source, result, "<stdin>")
            sys.stdout.write(diff+"\n" if diff else "\n")
        else:
            sys.stdout.write(result)
        return 0
    # non-stdin file read (config error style)
    try:
        with open(target,'rb') as f:
            data=f.read()
    except OSError as e:
        raise ConfigError(f"path error: {io_error_str(e)}")
    try:
        source=data.decode('utf-8')
    except UnicodeDecodeError:
        raise ConfigError("path error: stream did not contain valid UTF-8")
    if dry:
        status, result = single_attempt(source, line, col)
        diff=unified_diff(source, result, "<stdin>")
        sys.stdout.write(diff+"\n" if diff else "\n")
        return 0
    status, result = single_attempt(source, line, col)
    if status=="oob":
        sys.stderr.write(f"single fix error: position out of bounds: line {line}, col {col}\n")
        return 0
    if status!="fixed":
        sys.stderr.write("single fix error: nothing to fix\n")
        return 0
    # write to file literally named <stdin> in cwd (original bug)
    try:
        with open("<stdin>",'w',encoding='utf-8',newline='') as f:
            f.write(result)
    except OSError:
        pass
    return 0

def do_explain(positionals):
    # validation already done
    code=positionals[0]  # parsed code int
    if code==0:
        sys.stdout.write("syntax error\n"); return 0
    text=_EXPLAIN_TEXT.get(code)
    if text is None:
        sys.stderr.write(f"explain error: lint with code `{code}` not found\n"); return 0
    sys.stdout.write(text); return 0

_EXPLAIN_TEXT = {}

def main(argv):
    # reconfigure outputs
    try:
        sys.stdout.reconfigure(encoding='utf-8', errors='surrogateescape')
    except Exception: pass
    try:
        sys.stderr.reconfigure(encoding='utf-8', errors='surrogateescape')
    except Exception: pass
    args=argv[1:]
    try:
        if not args:
            raise ClapExit(TOP_HELP.format(bin=BIN_NAME),2)
        # help subcommand special
        if args[0]=="help":
            rest=args[1:]
            if not rest:
                sys.stdout.write(TOP_HELP.format(bin=BIN_NAME)); return 0
            first=rest[0]
            if first in SUB_HELP and len(rest)==1:
                sys.stdout.write(SUB_HELP[first].format(bin=BIN_NAME)); return 0
            if first in SUB_HELP and len(rest)>1:
                bad=rest[1]
                raise ClapExit(f"error:  The subcommand '{bad}' wasn't recognized\n\nUSAGE:\n    {BIN_NAME} <subcommands>\n\nFor more information try --help\n",2)
            raise ClapExit(f"error:  The subcommand '{first}' wasn't recognized\n\nUSAGE:\n    {BIN_NAME} <subcommands>\n\nFor more information try --help\n",2)
        # top level flags / subcommand
        first=args[0]
        if first in ("-h","--help") or first.startswith("--help=") or (first.startswith("-") and first[1:2]=="h" and not first.startswith("--")):
            sys.stdout.write(TOP_HELP.format(bin=BIN_NAME)); return 0
        if first in ("-V","--version") or first.startswith("--version="):
            sys.stdout.write("statix 0.5.8\n"); return 0
        if first=="--" :
            # no subcommand
            raise ClapExit(TOP_HELP.format(bin=BIN_NAME),2)
        if first.startswith("-"):
            # unknown top arg; check suggestion / subcommand-put suggestion
            body=first[2:] if first.startswith("--") else first[1:]
            # subcommand-put: if any following token is a subcommand that has this long flag
            if first.startswith("--"):
                name=body.split("=",1)[0]
                for tok in args[1:]:
                    if tok in OPT_SPECS and opt_by_long(tok, name) is not None:
                        raise clap_error_found_arg(f"--{name}", "top", subcmd_put_suggestion=tok, usage_override=fmt_usage("top"))
                cand=did_you_mean(name, ["help","version"])
                if cand:
                    raise clap_error_found_arg(f"--{name}", "top", suggestion=f"--{cand}", usage_override=f"{BIN_NAME} --{cand}")
                raise clap_error_found_arg(first.split("=",1)[0] if first.startswith("--") else first, "top")
            else:
                # short cluster first char unknown at top (h/V already handled)
                raise clap_error_found_arg(f"-{first[1]}", "top")
        if first not in SUBCOMMANDS and first!="help":
            # subcommand suggestion?
            cand=did_you_mean(first, SUBCOMMANDS+["help"])
            if cand:
                msg=f"error: The subcommand '{first}' wasn't recognized\n\n\tDid you mean '{cand}'?\n\nIf you believe you received this message in error, try re-running with '{BIN_NAME} -- {first}'\n\nUSAGE:\n    {fmt_usage('top')}\n\nFor more information try --help\n"
                raise ClapExit(msg,2)
            raise clap_error_found_arg(first, "top", supply_hint=False)
        cmd=first
        sub_args=args[1:]
        # list/dump/explain/check/fix/single parse
        values, positionals = parse_subcommand_args(cmd, sub_args)
        if cmd=="list":
            ensure_no_extra(cmd, positionals, 0)
            out="".join(f"W{code:02d} {name}\n" for code,(name,title) in sorted(LINT_INFO.items()))
            sys.stdout.write(out); return 0
        if cmd=="dump":
            ensure_no_extra(cmd, positionals, 0)
            sys.stdout.write("disabled = []\nignore = ['.direnv']\n\n"); return 0
        if cmd=="explain":
            if not positionals:
                raise missing_required(cmd, ["<TARGET>"])
            # validate code first? If extra, original may... do code validation before extra check? we'll validate code
            status, res = validate_warning_code(positionals[0])
            if status=="error":
                raise ClapExit(f"error: Invalid value for '<TARGET>': {res}\n\nFor more information try --help\n",2)
            ensure_no_extra(cmd, positionals, 1)
            return do_explain([res])
        if cmd=="single":
            # required position
            if "position" not in values:
                raise missing_required(cmd, ["--position <POSITION>"])
            status,res = validate_position(values["position"])
            if status=="error":
                raise ClapExit(f"error: Invalid value for '--position <POSITION>': {res}\n\nFor more information try --help\n",2)
            values["_position_parsed"]=res
            return do_single(cmd, values, positionals)
        if cmd=="check":
            return do_check(cmd, values, positionals)
        if cmd=="fix":
            return do_fix(cmd, values, positionals)
        return 0
    except ClapExit as e:
        if e.to_stdout:
            sys.stdout.write(e.text)
        else:
            sys.stderr.write(e.text)
        return e.code
    except ConfigError as e:
        sys.stderr.write(f"config error: {e}\n")
        return 0

if __name__=="__main__":
    sys.exit(main(sys.argv))
PYEOF
"}

