                return ("fixed", apply_suggestion(source, rep.suggestion))
    return ("nothing", source)

def do_single(cmd, values, positionals):
    # required position check is handled before call
    ensure_no_extra(cmd, positionals, 1)
    target=positionals[0] if positionals else None
    stdin_flag=bool(values.get("stdin",False))
    dry=bool(values.get("dry-run",False))
    pos=values["_position_parsed"]
    line,col=pos
    if not stdin_flag and target is None:
        panic(PANIC_SINGLE_NO_TARGET, "called `Option::unwrap()` on a `None` value")
    if stdin_flag:
        source=read_stdin_text(PANIC_STDIN_SINGLE)
        status, result = single_attempt(source, line, col)
        if dry:
            diff=unified_diff(source, result, "<stdin>")
            sys.stdout.write(diff+"\n" if diff else "\n")
        else:
            sys.stdout.write(result)
        return 0
    # non-stdin file read (config error style)
    try:
        with open(target,'rb') as f:
            data=f.read()
    except OSError as e:
        raise ConfigError(f"path error: {io_error_str(e)}")
    try:
        source=data.decode('utf-8')
    except UnicodeDecodeError:
        raise ConfigError("path error: stream did not contain valid UTF-8")
    if dry:
        status, result = single_attempt(source, line, col)
        diff=unified_diff(source, result, "<stdin>")
        sys.stdout.write(diff+"\n" if diff else "\n")
        return 0
    status, result = single_attempt(source, line, col)
    if status=="oob":
        sys.stderr.write(f"single fix error: position out of bounds: line {line}, col {col}\n")
        return 0
    if status!="fixed":
        sys.stderr.write("single fix error: nothing to fix\n")
        return 0
    # write to file literally named <stdin> in cwd (original bug)
    try:
        with open("<stdin>",'w',encoding='utf-8',newline='') as f:
            f.write(result)
    except OSError:
        pass
    return 0

def do_explain(positionals):
    # validation already done
    code=positionals[0]  # parsed code int
    if code==0:
        sys.stdout.write("syntax error\n"); return 0
    text=_EXPLAIN_TEXT.get(code)
    if text is None:
        sys.stderr.write(f"explain error: lint with code `{code}` not found\n"); return 0
    sys.stdout.write(text); return 0

_EXPLAIN_TEXT = {}

def main(argv):
    # reconfigure outputs
    try:
        sys.stdout.reconfigure(encoding='utf-8', errors='surrogateescape')
    except Exception: pass
    try:
        sys.stderr.reconfigure(encoding='utf-8', errors='surrogateescape')
    except Exception: pass
    args=argv[1:]
    try:
        if not args:
            raise ClapExit(TOP_HELP.format(bin=BIN_NAME),2)
        # help subcommand special
        if args[0]=="help":
            rest=args[1:]
            if not rest:
                sys.stdout.write(TOP_HELP.format(bin=BIN_NAME)); return 0
            first=rest[0]
            if first in SUB_HELP and len(rest)==1:
                sys.stdout.write(SUB_HELP[first].format(bin=BIN_NAME)); return 0
            if first in SUB_HELP and len(rest)>1:
                bad=rest[1]
                raise ClapExit(f"error:  The subcommand '{bad}' wasn't recognized\n\nUSAGE:\n    {BIN_NAME} <subcommands>\n\nFor more information try --help\n",2)
            raise ClapExit(f"error:  The subcommand '{first}' wasn't recognized\n\nUSAGE:\n    {BIN_NAME} <subcommands>\n\nFor more information try --help\n",2)
        # top level flags / subcommand
        first=args[0]
        if first in ("-h","--help") or first.startswith("--help=") or (first.startswith("-") and first[1:2]=="h" and not first.startswith("--")):
            sys.stdout.write(TOP_HELP.format(bin=BIN_NAME)); return 0
        if first in ("-V","--version") or first.startswith("--version="):
            sys.stdout.write("statix 0.5.8\n"); return 0
        if first=="--" :
            # no subcommand
            raise ClapExit(TOP_HELP.format(bin=BIN_NAME),2)
        if first.startswith("-"):
            # unknown top arg; check suggestion / subcommand-put suggestion
            body=first[2:] if first.startswith("--") else first[1:]
            # subcommand-put: if any following token is a subcommand that has this long flag
            if first.startswith("--"):
                name=body.split("=",1)[0]
                for tok in args[1:]:
                    if tok in OPT_SPECS and opt_by_long(tok, name) is not None:
                        raise clap_error_found_arg(f"--{name}", "top", subcmd_put_suggestion=tok, usage_override=fmt_usage("top"))
                cand=did_you_mean(name, ["help","version"])
                if cand:
                    raise clap_error_found_arg(f"--{name}", "top", suggestion=f"--{cand}", usage_override=f"{BIN_NAME} --{cand}")
                raise clap_error_found_arg(first.split("=",1)[0] if first.startswith("--") else first, "top")
            else:
                # short cluster first char unknown at top (h/V already handled)
                raise clap_error_found_arg(f"-{first[1]}", "top")
        if first not in SUBCOMMANDS and first!="help":
            # subcommand suggestion?
            cand=did_you_mean(first, SUBCOMMANDS+["help"])
            if cand:
                msg=f"error: The subcommand '{first}' wasn't recognized\n\n\tDid you mean '{cand}'?\n\nIf you believe you received this message in error, try re-running with '{BIN_NAME} -- {first}'\n\nUSAGE:\n    {fmt_usage('top')}\n\nFor more information try --help\n"
                raise ClapExit(msg,2)
            raise clap_error_found_arg(first, "top", supply_hint=False)
        cmd=first
        sub_args=args[1:]
        # list/dump/explain/check/fix/single parse
        values, positionals = parse_subcommand_args(cmd, sub_args)
        if cmd=="list":
            ensure_no_extra(cmd, positionals, 0)
            out="".join(f"W{code:02d} {name}\n" for code,(name,title) in sorted(LINT_INFO.items()))
            sys.stdout.write(out); return 0
        if cmd=="dump":
            ensure_no_extra(cmd, positionals, 0)
            sys.stdout.write("disabled = []\nignore = ['.direnv']\n\n"); return 0
        if cmd=="explain":
            if not positionals:
                raise missing_required(cmd, ["<TARGET>"])
            # validate code first? If extra, original may... do code validation before extra check? we'll validate code
            status, res = validate_warning_code(positionals[0])
            if status=="error":
                raise ClapExit(f"error: Invalid value for '<TARGET>': {res}\n\nFor more information try --help\n",2)
            ensure_no_extra(cmd, positionals, 1)
            return do_explain([res])
        if cmd=="single":
            # required position
            if "position" not in values:
                raise missing_required(cmd, ["--position <POSITION>"])
            status,res = validate_position(values["position"])
            if status=="error":
                raise ClapExit(f"error: Invalid value for '--position <POSITION>': {res}\n\nFor more information try --help\n",2)
            values["_position_parsed"]=res
            return do_single(cmd, values, positionals)
        if cmd=="check":
            return do_check(cmd, values, positionals)
        if cmd=="fix":
            return do_fix(cmd, values, positionals)
        return 0
    except ClapExit as e:
        if e.to_stdout:
            sys.stdout.write(e.text)
        else:
            sys.stderr.write(e.text)
        return e.code
    except ConfigError as e:
        sys.stderr.write(f"config error: {e}\n")
        return 0

if __name__=="__main__":
    sys.exit(main(sys.argv))
