import subprocess, pathlib, shutil, sys, os
ORIG="/workspace/executable"; MINE="/tmp/mybin/executable"
def run_bin(binpath, args, cwd, inp=None):
    return subprocess.run([binpath]+args, capture_output=True, cwd=cwd, input=inp)
def compare_case(name, setup_func, args, inp=None):
    # setup_func(dirpath) creates files fresh for each bin
    results=[]
    for label,binpath in [("orig",ORIG),("mine",MINE)]:
        d=pathlib.Path(f"/tmp/difft_{label}")
        if d.exists(): shutil.rmtree(d)
        d.mkdir()
        if setup_func: setup_func(d)
        r=run_bin(binpath,args,d,inp)
        files={}
        for p in sorted(d.rglob("*")):
            if p.is_file():
                try: files[str(p.relative_to(d))]=p.read_bytes()
                except: pass
        results.append((r.returncode,r.stdout,r.stderr,files))
    if results[0]!=results[1]:
        print(f"FAIL {name} args={args}")
        for label,res in zip(["orig","mine"],results):
            print(f" {label}: exit={res[0]} stdout={res[1][:800]!r} stderr={res[2][:800]!r} files={res[3]}")
        return False
    else:
        print(f"ok {name}")
        return True

def content_setup(content, fname="a.nix"):
    def setup(d): (d/fname).write_text(content)
    return setup
