                if body.startswith("0o"):
                    return TomlValue("integer", int(t_clean,8), line, col)
                if body.startswith("0b"):
                    return TomlValue("integer", int(t_clean,2), line, col)
                if is_float:
                    return TomlValue("float", float(t_clean), line, col, raw=token)
