    def _validate_toml_number(self, token, start):
        # returns True if float; raises ConfigError for invalid numbers
        i=1 if token[:1] in ('+','-') else 0
        rest=token[i:]
        # base-prefixed integers
        if rest[:2].lower() in ("0x","0o","0b"):
            base={'0x':16,'0o':8,'0b':2}[rest[:2].lower()]
            valid="0123456789abcdefABCDEF" if base==16 else ("01234567" if base==8 else "01")
            digits=rest[2:]
            if digits=="":
                self._invalid_number(start+i+2)
            for k,ch in enumerate(digits):
                if ch=='_':
                    continue
                if ch not in valid:
                    self._invalid_number(start+i+2+k)
